import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        new Main().run();
    }

    void run() {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int mod = 998244353;
        int n = in.nextInt();
        int k = in.nextInt();
        int[] v = new int[10];
        for (int i = 0; i < k; i++) {
            int x = in.nextInt();
            v[x] = 1;
        }
        int[] ans = {1};
        int p = n / 2;
        while (true) {
            if (p % 2 != 0) {
                ans = multiplyMod(ans, v, mod);
            }
            p /= 2;
            if (p == 0) break;
            v = multiplyMod(v, v, mod);
        }
        int res = 0;
        for (int x : ans) {
            res = (int) ((res + (long) x * x) % mod);
        }
        out.println(res);
        out.close();
    }

    int[] multiplyMod(int[] a, int[] b, int mod) {
        int need = a.length + b.length - 1;
        int n = Math.max(2, Integer.highestOneBit(need - 1) << 1);

        double[] aReal = new double[n];
        double[] aImaginary = new double[n];
        for (int i = 0; i < a.length; i++) {
            int x = (a[i] % mod + mod) % mod;
            aReal[i] = x & ((1 << 15) - 1);
            aImaginary[i] = x >> 15;
        }
        fft(aReal, aImaginary, false);

        double[] bReal = new double[n];
        double[] bImaginary = new double[n];
        for (int i = 0; i < b.length; i++) {
            int x = (b[i] % mod + mod) % mod;
            bReal[i] = x & ((1 << 15) - 1);
            bImaginary[i] = x >> 15;
        }
        fft(bReal, bImaginary, false);

        double[] faReal = new double[n];
        double[] faImaginary = new double[n];
        double[] fbReal = new double[n];
        double[] fbImaginary = new double[n];

        for (int i = 0; i < n; i++) {
            int j = (n - i) & (n - 1);

            double a1r = (aReal[i] + aReal[j]) / 2;
            double a1i = (aImaginary[i] - aImaginary[j]) / 2;
            double a2r = (aImaginary[i] + aImaginary[j]) / 2;
            double a2i = (aReal[j] - aReal[i]) / 2;

            double b1r = (bReal[i] + bReal[j]) / 2;
            double b1i = (bImaginary[i] - bImaginary[j]) / 2;
            double b2r = (bImaginary[i] + bImaginary[j]) / 2;
            double b2i = (bReal[j] - bReal[i]) / 2;

            faReal[i] = a1r * b1r - a1i * b1i - a2r * b2i - a2i * b2r;
            faImaginary[i] = a1r * b1i + a1i * b1r + a2r * b2r - a2i * b2i;

            fbReal[i] = a1r * b2r - a1i * b2i + a2r * b1r - a2i * b1i;
            fbImaginary[i] = a1r * b2i + a1i * b2r + a2r * b1i + a2i * b1r;
        }

        fft(faReal, faImaginary, true);
        fft(fbReal, fbImaginary, true);
        int[] res = new int[need];
        for (int i = 0; i < need; i++) {
            long aa = Math.round(faReal[i]);
            long bb = Math.round(fbReal[i]);
            long cc = Math.round(faImaginary[i]);
            res[i] = (int) ((aa + ((bb % mod) << 15) + ((cc % mod) << 30)) % mod);
        }
        return res;
    }

    void fft(double[] a, double[] b, boolean inverse) {
        int n = a.length;
        int shift = 32 - Integer.numberOfTrailingZeros(n);
        for (int i = 1; i < n; i++) {
            int j = Integer.reverse(i << shift);
            if (i < j) {
                double temp = a[i];
                a[i] = a[j];
                a[j] = temp;
                temp = b[i];
                b[i] = b[j];
                b[j] = temp;
            }
        }
        for (int len = 2; len <= n; len <<= 1) {
            int halfLen = len >> 1;
            double[] cs = new double[halfLen];
            double[] sn = new double[halfLen];
            for (int i = 0; i < halfLen; i++) {
                double angle = 2 * Math.PI * i / len * (inverse ? -1 : 1);
                cs[i] = Math.cos(angle);
                sn[i] = Math.sin(angle);
            }
            for (int i = 0; i < n; i += len) {
                for (int j = 0; j < halfLen; j++) {
                    double wA = cs[j];
                    double wB = sn[j];
                    double uA = a[i + j];
                    double uB = b[i + j];
                    double vA = a[i + j + halfLen] * wA - b[i + j + halfLen] * wB;
                    double vB = a[i + j + halfLen] * wB + b[i + j + halfLen] * wA;
                    a[i + j] = uA + vA;
                    b[i + j] = uB + vB;
                    a[i + j + halfLen] = uA - vA;
                    b[i + j + halfLen] = uB - vB;
                }
            }
        }
        if (inverse) {
            for (int i = 0; i < n; i++) {
                a[i] /= n;
                b[i] /= n;
            }
        }
    }

    static class InputReader {
        final InputStream is;
        final byte[] buf = new byte[1024];
        int pos, size;

        public InputReader(InputStream is) {
            this.is = is;
        }

        public int nextInt() {
            int c = read();
            while (isWhitespace(c)) c = read();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + c - '0';
                c = read();
            } while (!isWhitespace(c));
            return res * sign;
        }

        int read() {
            if (size == -1) throw new InputMismatchException();
            if (pos >= size) {
                pos = 0;
                try { size = is.read(buf); } catch (IOException e) { throw new InputMismatchException(); }
                if (size <= 0) return -1;
            }
            return buf[pos++] & 255;
        }

        static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}
